#!/usr/bin/env bash
#
# Write macos/Flutter/Google.xcconfig from .env.
#
# The macOS twin of scripts/gen-google-xcconfig.sh. Google Sign-In on macOS
# reads GIDClientID from Info.plist and only starts its flow if the bundle
# registers the reversed client id as a URL scheme. The Mac app has the
# iPhone's bundle id, so both come from the iOS client, GOOGLE_IOS_CLIENT_ID.
#
# The generated file is gitignored, so the client id stays out of this public
# repo. `make run-macos` and `make build-macos` run this first.

set -euo pipefail

cd "$(dirname "$0")/.."

env_file=".env"
out="macos/Flutter/Google.xcconfig"

if [ ! -f "$env_file" ]; then
  echo "gen-google-xcconfig (macos): $env_file is missing. Copy .env.example and fill it in." >&2
  exit 1
fi

client_id="$(grep -E '^GOOGLE_IOS_CLIENT_ID=' "$env_file" | head -n 1 | cut -d= -f2- | tr -d '"'"'"' \r')"

if [ -z "$client_id" ]; then
  echo "gen-google-xcconfig (macos): GOOGLE_IOS_CLIENT_ID is empty in $env_file." >&2
  echo "  Google sign-in on macOS cannot work without it." >&2
  exit 1
fi

case "$client_id" in
  *.apps.googleusercontent.com) ;;
  *)
    echo "gen-google-xcconfig (macos): GOOGLE_IOS_CLIENT_ID does not look like a Google client id." >&2
    exit 1
    ;;
esac

prefix="${client_id%.apps.googleusercontent.com}"
reversed="com.googleusercontent.apps.$prefix"

mkdir -p "$(dirname "$out")"
cat > "$out" <<EOF
// GENERATED by macos/gen-google-xcconfig.sh from .env. Do not edit, and do not
// commit: this file is gitignored so the client id stays out of a public repo.
GOOGLE_CLIENT_ID = $client_id
GOOGLE_REVERSED_CLIENT_ID = $reversed
EOF

echo "gen-google-xcconfig (macos): wrote $out"
